export class RateLimiter {
  private readonly limit: number;
  private readonly windowMs: number;
  private readonly hits = new Map<string, number[]>();

  constructor(limit: number, windowMs: number) {
    this.limit = limit;
    this.windowMs = windowMs;
  }

  isAllowed(key: string, headers: Headers): boolean {
    const now = Date.now();
    const clientIp = getClientIp(headers);
    const bucketKey = `${key}:${clientIp}`;
    const timestamps = this.hits.get(bucketKey) ?? [];
    const recent = timestamps.filter((timestamp) => now - timestamp < this.windowMs);

    if (recent.length >= this.limit) {
      this.hits.set(bucketKey, recent);
      return false;
    }

    recent.push(now);
    this.hits.set(bucketKey, recent);
    return true;
  }
}

export function getClientIp(headers: Headers): string {
  const forwarded = headers.get("x-forwarded-for");
  if (!forwarded) {
    return "unknown";
  }

  const first = forwarded.split(",")[0]?.trim();
  return first || "unknown";
}

export function isSafeRedirectUrl(value: string): boolean {
  try {
    const url = new URL(value);

    if (!["http:", "https:"].includes(url.protocol)) {
      return false;
    }

    if (url.hostname === "localhost") {
      return false;
    }

    if (url.hostname === "127.0.0.1" || url.hostname === "::1") {
      return false;
    }

    if (url.hostname.endsWith(".local")) {
      return false;
    }

    return true;
  } catch {
    return false;
  }
}
